  class HovborgLogo extends HTMLElement {
    static get observedAttributes() { return ['caption', 'paused']; }

    constructor() {
      super();
      this.attachShadow({ mode: 'open' }).append(template.content.cloneNode(true));
      this._resize = new ResizeObserver(entries => {
        this.style.setProperty('--hv-scale', String(entries[0].contentRect.width / 520));
      });
      this.shadowRoot.querySelector('input').addEventListener('change', event => {
        this.toggleAttribute('paused', event.target.checked);
      });
    }

    connectedCallback() {
      this._resize.observe(this);
      this._sync();
    }

    disconnectedCallback() { this._resize.disconnect(); }
    attributeChangedCallback() { this._sync(); }

    _sync() {
      this.shadowRoot.querySelector('.hv-sub').textContent = this.getAttribute('caption') || '';
      this.shadowRoot.querySelector('input').checked = this.hasAttribute('paused');
    }
  }

  customElements.define('hovborg-logo', HovborgLogo);
